function removeDuplicates(list) {
  if (list.length === 0) {
    return 0;
  }
  var write = 1;
  for (var read = 1; read < list.length; read++) {
    if (list[read] !== list[write - 1]) {
      list[write++] = list[read];
    }
  }
  list.length = write;
  return write;
}

var data = [1, 1, 2, 3, 3, 3, 4];
console.log(removeDuplicates(data));
